// Manual private-capture regression. Input is a local UDP JSON export, never bundled.
#include "xmcloud.h"
#include "dvrip.h"
#include <QtEndian>
#include <iostream>
int main(int argc,char **argv){QCoreApplication app(argc,argv);if(argc!=2 && argc!=3)return 2;QFile video; if(argc==3){video.setFileName(argv[2]);if(!video.open(QIODevice::WriteOnly|QIODevice::NewOnly))return 2;}QMap<int,xm::MediaParser> mediaParsers;int videoFrames=0;try{QFile f(argv[1]);if(!f.open(QIODevice::ReadOnly))return 2;auto records=QJsonDocument::fromJson(f.readAll()).array();QMap<int,int> strides;QMap<int,quint32> keys;QMap<QString,xm::cloud::Receiver> receivers;int messages=0,headers=0,capabilities=0,logins=0,media=0;for(auto v:records){auto o=v.toObject();int sp=o["sp"].toInt(),dp=o["dp"].toInt();auto b=QByteArray::fromHex(o["data"].toString().toLatin1());if(b.size()<4)continue;auto cmd=qFromLittleEndian<quint16>(b.constData()+2);if(dp==8765&&cmd==1004&&b.size()==364)strides[sp]=qFromLittleEndian<quint32>(b.constData()+360);if(sp==8765&&cmd==1005&&b.size()>=24)keys[dp]=qFromLittleEndian<quint32>(b.constData()+20);if((sp!=4999&&dp!=4999)||cmd!=2003||b.size()<24||(quint8(b[21])&1))continue;int port=sp==4999?dp:sp;auto &r=receivers[QString::number(port)+(sp==4999?"in":"out")];auto slice=b.mid(12);slice.replace(12,slice.size()-12,xm::cloud::crypt(slice.mid(12),keys[port],strides[port]));auto completed=r.accept(slice);for(int offset=0;offset<completed.size();){auto n=qFromLittleEndian<quint32>(completed.constData()+offset);offset+=4;auto p=completed.mid(offset,n);offset+=n;++messages;for(int pos=0;pos+20<=p.size();){auto size=xm::payloadSize(p.mid(pos,20));if(pos+20+size>p.size())throw std::runtime_error("Truncated captured DVRIP packet");auto id=qFromLittleEndian<quint16>(p.constData()+pos+14);auto body=p.mid(pos+20,size);++headers;if(id==1414&&qFromLittleEndian<quint32>(p.constData()+pos+4)==1100000-1){auto cap=QJsonDocument::fromJson(xm::cloud::aesDecode(body,xm::cloud::wrapperKey())).object();if(!cap["LoginEncryptionType"].toObject()["RSA"].toBool())return 3;++capabilities;}if(id==1000){auto login=QJsonDocument::fromJson(xm::cloud::aesDecode(body,xm::cloud::wrapperKey())).object();if(login["UserName"].toString().size()!=256)return 4;++logins;}if(id==1412){++media;auto &parser=mediaParsers[port];parser.append(body);while(true){auto frame=parser.take();if(frame.isEmpty())break;++videoFrames;if(video.isOpen()&&video.write(frame)!=frame.size())return 6;}}pos+=20+size;}}}std::cout<<"Messages "<<messages<<", DVRIP packets "<<headers<<", capabilities "<<capabilities<<", encrypted logins "<<logins<<", media packets "<<media<<", video frames "<<videoFrames<<"\n";return logins&&media&&videoFrames?0:5;}catch(const std::exception &e){std::cerr<<e.what()<<"\n";return 1;}}
